import json,os
X={}
for k,v in D.items():
    X[k]=dict(t=dict(call=v[0],wa='WhatsApp',write=v[1],sending=v[2],ok=v[3],fail=v[4],e_nome=v[5],e_mail=v[6],e_msg=v[7],subj='Website enquiry ('+k+')'),
              u=dict(q=v[8],o=v[9],hot=v[10]),et=v[11])
p=os.path.expanduser('~/mnt/danova_allestimenti/assets/js/contatto.js')
s=open(p,encoding='utf-8').read()
assert 'DTX_EXTRA' not in s
js="  /* 24/11/2026: testi del modulo in tutte le altre lingue del sito (prima ricadevano sull'inglese) */\n  var DTX_EXTRA="+json.dumps(X,ensure_ascii=False)+";\n"
js+="  function dtLk(){ var h=(document.documentElement.lang||'it').toLowerCase(); if(h.indexOf('zh-hant')===0||h.indexOf('zh-tw')===0||h.indexOf('zh-hk')===0) return 'zt'; return h.slice(0,2); }\n"
js+="  for(var _k in DTX_EXTRA){ if(!TX[_k]) TX[_k]=DTX_EXTRA[_k].t; }\n"
a="  var T=TX[L]||TX.en;"
assert s.count(a)==1
s=s.replace(a, js+"  L=dtLk();\n"+a)
b="  var lastForm=null;"
assert s.count(b)==1
s=s.replace(b,"  for(var _u in DTX_EXTRA){ if(!UTX[_u]) UTX[_u]=DTX_EXTRA[_u].u; }\n"+b)
c="function lang(){ var h=(document.documentElement.lang||'it').slice(0,2).toLowerCase(); return UTX[h]||UTX.en; }"
assert s.count(c)==1
s=s.replace(c,"function lang(){ return UTX[dtLk()]||UTX.en; }")
d="ET[(document.documentElement.lang||'it').slice(0,2).toLowerCase()]||ET.en"
assert s.count(d)==1
s=s.replace(d,"ET[dtLk()]||(DTX_EXTRA[dtLk()]&&DTX_EXTRA[dtLk()].et)||ET.en")
open(p,'w',encoding='utf-8').write(s)
print('ok',len(X))
